"""Fusion 360 script: chip chip2_encapsulation_emulsion_break_capsule_wash_curing (27.5 x 20.5 mm), generated by autochip/cad.py from chips/chip2_encapsulation_emulsion_break_capsule_wash_curing.json.
Run it in Fusion: Utilities > Scripts and Add-Ins, or send it through the Fusion MCP execute_code tool
(then set PARTS_DIR first). It
  1. imports every placed part (parts/<module>.stl, mm, chip origin) as its own component,
  2. sketches the board outline, the port circles and every channel centreline ("channel paths"),
  3. sketches every channel as a closed outline at its true width ("channel outlines"), ready to
     extrude-cut 0.3 mm into the fluidic layer (top of the fluidic layer at z = 1.5 mm).
Fusion's API works in cm; the numbers below are mm and converted on the way in.
"""
import adsk.core, adsk.fusion
import os

try:
    PARTS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "parts")
except NameError:
    PARTS_DIR = globals()["PARTS_DIR"]
BOARD = [27.5, 20.5]
PARTS = [["core_join", "merge"], ["core_mix", "mixer"], ["encap_junction", "droplet_junction"], ["capsule_trap", "trap_chamber"]]
CHANNELS = [["ch_inlet_1_core_join", 0.3, [[2.0, 14.97], [2.5, 14.97], [4.5, 14.97]]], ["ch_core_join_core_mix", 0.5, [[7.5, 14.97], [8.5, 14.97]]], ["ch_core_mix_encap_junction", 0.5, [[11.1, 14.97], [23.5, 14.97], [23.5, 12.79], [4.0, 12.79], [4.0, 7.07], [4.5, 7.07]]], ["ch_encap_junction_capsule_trap", 0.5, [[7.5, 7.07], [8.5, 7.07]]], ["ch_capsule_trap_outlet_1", 0.5, [[22.6421, 7.07], [25.0, 7.07], [25.5, 7.07]]], ["ch_core_solution_in_core_join", 0.25, [[6.0, 18.5], [6.0, 18.0], [6.0, 16.47]]], ["ch_shell_polymer_in_encap_junction", 0.25, [[6.0, 12.14], [6.0, 11.64], [6.0, 8.57]]], ["ch_fluorinated_oil_in_encap_junction", 0.25, [[6.0, 2.0], [6.0, 2.5], [6.0, 5.57]]], ["ch_emulsion_breaker_in_capsule_trap", 0.25, [[14.07, 12.14], [14.07, 11.64], [14.07, 10.6055]]], ["ch_wash_buffer_in_capsule_trap", 0.25, [[17.07, 12.14], [17.07, 11.64], [17.07, 10.6055]]], ["ch_capsule_trap_capsule_trap_waste_out", 0.25, [[15.57, 3.5345], [15.57, 2.5], [15.57, 2.0]]]]
OUTLINES = [["ch_inlet_1_core_join", [[2.0, 15.12], [4.5, 15.12], [4.5, 14.82], [2.0, 14.82]]], ["ch_core_join_core_mix", [[7.5, 15.22], [8.5, 15.22], [8.5, 14.72], [7.5, 14.72]]], ["ch_core_mix_encap_junction", [[11.1, 15.22], [23.75, 15.22], [23.75, 12.54], [4.25, 12.54], [4.25, 7.32], [4.5, 7.32], [4.5, 6.82], [3.75, 6.82], [3.75, 13.04], [23.25, 13.04], [23.25, 14.72], [11.1, 14.72]]], ["ch_encap_junction_capsule_trap", [[7.5, 7.32], [8.5, 7.32], [8.5, 6.82], [7.5, 6.82]]], ["ch_capsule_trap_outlet_1", [[22.6421, 7.32], [25.5, 7.32], [25.5, 6.82], [22.6421, 6.82]]], ["ch_core_solution_in_core_join", [[6.125, 18.5], [6.125, 16.47], [5.875, 16.47], [5.875, 18.5]]], ["ch_shell_polymer_in_encap_junction", [[6.125, 12.14], [6.125, 8.57], [5.875, 8.57], [5.875, 12.14]]], ["ch_fluorinated_oil_in_encap_junction", [[5.875, 2.0], [5.875, 5.57], [6.125, 5.57], [6.125, 2.0]]], ["ch_emulsion_breaker_in_capsule_trap", [[14.195, 12.14], [14.195, 10.6055], [13.945, 10.6055], [13.945, 12.14]]], ["ch_wash_buffer_in_capsule_trap", [[17.195, 12.14], [17.195, 10.6055], [16.945, 10.6055], [16.945, 12.14]]], ["ch_capsule_trap_capsule_trap_waste_out", [[15.695, 3.5345], [15.695, 2.0], [15.445, 2.0], [15.445, 3.5345]]]]
PORTS = [["inlet_1", 2.5, 14.97, 1.0], ["outlet_1", 25.0, 7.07, 1.0], ["core_solution_in", 6.0, 18.0, 1.0], ["shell_polymer_in", 6.0, 11.64, 1.0], ["fluorinated_oil_in", 6.0, 2.5, 1.0], ["emulsion_breaker_in", 14.07, 11.64, 1.0], ["wash_buffer_in", 17.07, 11.64, 1.0], ["capsule_trap_waste_out", 15.57, 2.5, 1.0]]


def P(xy, z=0.0):
    return adsk.core.Point3D.create(xy[0] / 10.0, xy[1] / 10.0, z / 10.0)


def run(context=None):
    app = adsk.core.Application.get()
    design = adsk.fusion.Design.cast(app.activeProduct)
    root = design.rootComponent
    for module_id, part in PARTS:
        occ = root.occurrences.addNewComponent(adsk.core.Matrix3D.create())
        comp = occ.component
        comp.name = module_id + " (" + part + ")"
        path = os.path.join(PARTS_DIR, module_id + ".stl")
        if design.designType == adsk.fusion.DesignTypes.ParametricDesignType:
            base = comp.features.baseFeatures.add()
            base.startEdit()
            comp.meshBodies.add(path, adsk.fusion.MeshUnits.MillimeterMeshUnit, base)
            base.finishEdit()
        else:
            comp.meshBodies.add(path, adsk.fusion.MeshUnits.MillimeterMeshUnit)
    sk = root.sketches.add(root.xYConstructionPlane)
    sk.name = "chip2_encapsulation_emulsion_break_capsule_wash_curing outline + ports + channel paths"
    lines = sk.sketchCurves.sketchLines
    lines.addTwoPointRectangle(P((0, 0)), P(BOARD))
    for pid, x, y, d in PORTS:
        sk.sketchCurves.sketchCircles.addByCenterRadius(P((x, y)), d / 20.0)
    for cid, width, pts in CHANNELS:
        for a, b in zip(pts[:-1], pts[1:]):
            lines.addByTwoPoints(P(a), P(b))
    sk2 = root.sketches.add(root.xYConstructionPlane)
    sk2.name = "chip2_encapsulation_emulsion_break_capsule_wash_curing channel outlines (true width)"
    for cid, pts in OUTLINES:
        for a, b in zip(pts, pts[1:] + pts[:1]):
            sk2.sketchCurves.sketchLines.addByTwoPoints(P(a), P(b))
    app.activeViewport.fit()
    return "imported %d parts, sketched %d channels and %d ports" % (len(PARTS), len(CHANNELS), len(PORTS))
